"""Cleaning, deduplication, validation and reporting for JSONL datasets."""

from __future__ import annotations

import hashlib
import re
import statistics
from collections import Counter
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Iterable

from .records import detect_schema, read_jsonl, record_text, validate_record, write_jsonl
from .secrets import contains_secret, redact

MIN_RECORD_CHARS = 40
MAX_RECORD_CHARS = 120_000
MAX_LINE_LENGTH = 2_000
MAX_NON_ASCII_RATIO = 0.35

GENERATED_MARKERS = (
    "@generated",
    "auto-generated",
    "autogenerated",
    "do not edit",
    "code generated by",
    "this file was generated",
)

_WHITESPACE_RUN = re.compile(r"[ \t]+$", re.MULTILINE)
_BLANK_RUN = re.compile(r"\n{4,}")


# --------------------------------------------------------------------- cleaning
@dataclass
class CleanStats:
    read: int = 0
    kept: int = 0
    dropped_short: int = 0
    dropped_long: int = 0
    dropped_generated: int = 0
    dropped_minified: int = 0
    dropped_non_ascii: int = 0
    dropped_invalid: int = 0
    redacted_secrets: int = 0

    def as_dict(self) -> dict[str, int]:
        return self.__dict__.copy()


def normalize_text(text: str) -> str:
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    text = _WHITESPACE_RUN.sub("", text)
    text = _BLANK_RUN.sub("\n\n\n", text)
    return text.strip()


def looks_generated(text: str) -> bool:
    head = text[:2000].lower()
    return any(marker in head for marker in GENERATED_MARKERS)


def looks_minified(text: str) -> bool:
    lines = text.splitlines() or [text]
    if not lines:
        return False
    longest = max(len(line) for line in lines)
    average = sum(len(line) for line in lines) / len(lines)
    return longest > MAX_LINE_LENGTH and average > 400


def non_ascii_ratio(text: str) -> float:
    if not text:
        return 0.0
    non_ascii = sum(1 for character in text if ord(character) > 127)
    return non_ascii / len(text)


def clean_records(
    records: Iterable[dict[str, Any]],
    *,
    redact_secrets: bool = True,
    drop_secret_records: bool = False,
    min_chars: int = MIN_RECORD_CHARS,
    max_chars: int = MAX_RECORD_CHARS,
) -> tuple[list[dict[str, Any]], CleanStats]:
    stats = CleanStats()
    kept: list[dict[str, Any]] = []

    for record in records:
        stats.read += 1
        schema_name = detect_schema(record)
        if schema_name is None:
            stats.dropped_invalid += 1
            continue

        cleaned = _clean_record_fields(record)
        text = record_text(cleaned)

        if len(text) < min_chars:
            stats.dropped_short += 1
            continue
        if len(text) > max_chars:
            stats.dropped_long += 1
            continue
        if looks_generated(text):
            stats.dropped_generated += 1
            continue
        if looks_minified(text):
            stats.dropped_minified += 1
            continue
        if non_ascii_ratio(text) > MAX_NON_ASCII_RATIO:
            stats.dropped_non_ascii += 1
            continue

        if contains_secret(text):
            if drop_secret_records:
                stats.dropped_invalid += 1
                continue
            if redact_secrets:
                cleaned = _apply(cleaned, redact)
                stats.redacted_secrets += 1

        kept.append(cleaned)
        stats.kept += 1

    return kept, stats


def _clean_record_fields(record: dict[str, Any]) -> dict[str, Any]:
    return _apply(record, normalize_text)


def _apply(record: dict[str, Any], transform) -> dict[str, Any]:
    updated = dict(record)
    if isinstance(updated.get("messages"), list):
        updated["messages"] = [
            {**message, "content": transform(str(message.get("content", "")))}
            for message in updated["messages"]
            if isinstance(message, dict)
        ]
    for key in ("text", "instruction", "input", "output"):
        if isinstance(updated.get(key), str):
            updated[key] = transform(updated[key])
    return updated


# ---------------------------------------------------------------- deduplication
def _stable_hash(value: str) -> int:
    """Deterministic 32-bit hash. Python's built-in hash() is salted per process."""

    return int.from_bytes(
        hashlib.blake2b(value.encode("utf-8"), digest_size=4).digest(), "little"
    )


def _shingles(text: str, width: int = 5) -> set[int]:
    tokens = re.findall(r"[A-Za-z0-9_]+", text.lower())
    if len(tokens) < width:
        return {_stable_hash(" ".join(tokens))} if tokens else set()
    return {
        _stable_hash(" ".join(tokens[index : index + width]))
        for index in range(len(tokens) - width + 1)
    }


def _minhash(text: str, permutations: int = 64) -> tuple[int, ...]:
    """Cheap MinHash sketch used for near-duplicate detection."""

    shingle_set = _shingles(text)
    if not shingle_set:
        return tuple([0] * permutations)
    sketch = []
    for salt in range(permutations):
        sketch.append(min((shingle ^ (salt * 0x9E3779B1)) & 0xFFFFFFFF for shingle in shingle_set))
    return tuple(sketch)


def _sketch_similarity(left: tuple[int, ...], right: tuple[int, ...]) -> float:
    if not left or not right:
        return 0.0
    matches = sum(1 for a, b in zip(left, right) if a == b)
    return matches / len(left)


@dataclass
class DedupeStats:
    read: int = 0
    kept: int = 0
    exact_duplicates: int = 0
    near_duplicates: int = 0

    def as_dict(self) -> dict[str, int]:
        return self.__dict__.copy()


def dedupe_records(
    records: Iterable[dict[str, Any]],
    *,
    near_duplicates: bool = True,
    similarity_threshold: float = 0.85,
) -> tuple[list[dict[str, Any]], DedupeStats]:
    stats = DedupeStats()
    seen_hashes: set[str] = set()
    sketches: list[tuple[int, ...]] = []
    kept: list[dict[str, Any]] = []

    for record in records:
        stats.read += 1
        text = record_text(record)
        digest = hashlib.sha256(re.sub(r"\s+", " ", text).strip().encode("utf-8")).hexdigest()
        if digest in seen_hashes:
            stats.exact_duplicates += 1
            continue
        seen_hashes.add(digest)

        if near_duplicates:
            sketch = _minhash(text)
            if any(
                _sketch_similarity(sketch, existing) >= similarity_threshold
                for existing in sketches
            ):
                stats.near_duplicates += 1
                continue
            sketches.append(sketch)

        kept.append(record)
        stats.kept += 1

    return kept, stats


# ------------------------------------------------------------------ validation
@dataclass
class ValidationReport:
    path: str
    total_records: int = 0
    valid_records: int = 0
    invalid_records: int = 0
    duplicate_records: int = 0
    secret_hits: int = 0
    issues: list[dict[str, Any]] = field(default_factory=list)

    def as_dict(self) -> dict[str, Any]:
        return {
            "path": self.path,
            "total_records": self.total_records,
            "valid_records": self.valid_records,
            "invalid_records": self.invalid_records,
            "duplicate_records": self.duplicate_records,
            "secret_hits": self.secret_hits,
            "issues": self.issues,
        }


def validate_file(
    path: Path,
    schema_name: str = "sft_chat",
    *,
    max_records: int | None = None,
    max_issues: int = 200,
) -> ValidationReport:
    report = ValidationReport(path=str(path))
    seen: set[str] = set()

    for line_number, record, error in read_jsonl(path, limit=max_records):
        report.total_records += 1
        if error or record is None:
            report.invalid_records += 1
            if len(report.issues) < max_issues:
                report.issues.append({"line": line_number, "field": None, "problem": error})
            continue

        problems = validate_record(record, schema_name)
        if problems:
            report.invalid_records += 1
            for problem in problems:
                if len(report.issues) < max_issues:
                    report.issues.append({"line": line_number, "field": None, "problem": problem})
            continue

        text = record_text(record)
        digest = hashlib.sha256(re.sub(r"\s+", " ", text).strip().encode("utf-8")).hexdigest()
        if digest in seen:
            report.duplicate_records += 1
        seen.add(digest)

        if contains_secret(text):
            report.secret_hits += 1
            if len(report.issues) < max_issues:
                report.issues.append(
                    {
                        "line": line_number,
                        "field": None,
                        "problem": "possible credential detected; review before training",
                    }
                )

        report.valid_records += 1

    return report


# ---------------------------------------------------------------------- report
def build_report(path: Path, *, max_records: int | None = None) -> dict[str, Any]:
    lengths: list[int] = []
    languages: Counter[str] = Counter()
    licenses: Counter[str] = Counter()
    sources: Counter[str] = Counter()
    total_characters = 0
    total_records = 0
    warnings: list[str] = []

    for _line_number, record, error in read_jsonl(path, limit=max_records):
        if error or record is None:
            continue
        total_records += 1
        text = record_text(record)
        lengths.append(len(text))
        total_characters += len(text)
        meta = record.get("meta") or {}
        languages[str(meta.get("language", "unknown"))] += 1
        licenses[str(meta.get("license", "UNKNOWN"))] += 1
        sources[str(meta.get("source", "unknown"))] += 1

    percentiles: dict[str, float] = {}
    if lengths:
        ordered = sorted(lengths)
        percentiles = {
            "p50": float(statistics.median(ordered)),
            "p90": float(ordered[int(len(ordered) * 0.9) - 1]),
            "p99": float(ordered[int(len(ordered) * 0.99) - 1]),
            "max": float(ordered[-1]),
            "min": float(ordered[0]),
        }

    from .licenses import redistribution_warning

    warnings.append(
        "Review every upstream license before you redistribute this dataset, "
        "publish weights fine-tuned on it, or use either commercially."
    )
    warnings.extend(redistribution_warning(dict(licenses)))
    if total_records < 200:
        warnings.append(
            f"Only {total_records} records. A LoRA run on this little data will "
            "overfit quickly. Aim for a few thousand high-quality examples."
        )

    return {
        "path": str(path),
        "total_records": total_records,
        "total_characters": total_characters,
        "approx_tokens": total_characters // 4,
        "language_counts": dict(languages.most_common()),
        "license_counts": dict(licenses.most_common()),
        "source_counts": dict(sources.most_common()),
        "length_percentiles": percentiles,
        "warnings": warnings,
    }


def clean_file(
    input_path: Path,
    output_path: Path,
    *,
    dedupe: bool = True,
    redact_secrets: bool = True,
    drop_secret_records: bool = False,
) -> dict[str, Any]:
    records = [record for _n, record, error in read_jsonl(input_path) if record and not error]
    cleaned, clean_stats = clean_records(
        records, redact_secrets=redact_secrets, drop_secret_records=drop_secret_records
    )
    dedupe_stats = DedupeStats(read=len(cleaned), kept=len(cleaned))
    if dedupe:
        cleaned, dedupe_stats = dedupe_records(cleaned)
    written = write_jsonl(output_path, cleaned)
    return {
        "input_path": str(input_path),
        "output_path": str(output_path),
        "written": written,
        "clean": clean_stats.as_dict(),
        "dedupe": dedupe_stats.as_dict(),
    }
